#include <iostream>
using namespace std;
class Base {
    public:
        void who() { cout << "Base"; }
};
class Derived : public Base {
    public:
        void who() { cout << "Derived"; }
};

int main() {
    Derived d;
    Base *p = &d;
    p->who();
}

