#include <iostream>
#include <string>
using namespace std;
template <typename T>
class Box {
    private:
        T item;
    public:
        Box(T v) { item = v; }
        T get() const { return item; }
};

int main() {
    Box<int> a(42);
    Box<string> b("hi");
    cout << a.get() << " " << b.get();
}
